/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::NO_SUCH_CRITERION,
    error_codes::NO_VETTING,
    error_codes::APPROVER_NOT_SIGNER,
    error_codes::APPROVER_IN_EVENT,
    error_codes::SIGNER_CHANGED,
    error_codes::OTHER_CRITERION,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vtc/vetting/hidden/publish:noSuchCriterion`
    ///
    /// `criterionId` does not name an Accepts criterion this community has stored.
    ///
    /// Declared `retryable: false`.
    pub const NO_SUCH_CRITERION: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/vetting/hidden/publish:noSuchCriterion",
        retryable: false,
    };
    /// `vtc/vetting/hidden/publish:noVetting`
    ///
    /// The named criterion asks for no vetting requirements at all, so there is nothing for hidden-vetting parameters to qualify. Give the criterion vetting requirements first.
    ///
    /// Declared `retryable: false`.
    pub const NO_VETTING: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/vetting/hidden/publish:noVetting",
        retryable: false,
    };
    /// `vtc/vetting/hidden/publish:approverNotSigner`
    ///
    /// An event's `approvedBy` is new or changed relative to the stored configuration and does not name the publishing signer's principal. An approver names themselves; nobody approves on another's behalf.
    ///
    /// Declared `retryable: false`.
    pub const APPROVER_NOT_SIGNER: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/vetting/hidden/publish:approverNotSigner",
        retryable: false,
    };
    /// `vtc/vetting/hidden/publish:approverInEvent`
    ///
    /// An event's `approvedBy` names a member who has themselves asked to vet at that event through `vtc/vetting/vetters/event-mode`. A vetter cannot approve the event it asked to join.
    ///
    /// Declared `retryable: false`.
    pub const APPROVER_IN_EVENT: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/vetting/hidden/publish:approverInEvent",
        retryable: false,
    };
    /// `vtc/vetting/hidden/publish:signerChanged`
    ///
    /// The criterion's stored helper and token keys are not the ones the community's current credential-signer secret derives — the signer was rotated, or the community was restored under another key. Re-publishing would re-key silently and every enrolled vetter's credential would stop verifying. Withdraw hidden vetting from the criterion and publish it again, under a new period, to start a new key generation.
    ///
    /// Declared `retryable: false`.
    pub const SIGNER_CHANGED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/vetting/hidden/publish:signerChanged",
        retryable: false,
    };
    /// `vtc/vetting/hidden/publish:otherCriterion`
    ///
    /// Hidden vetting is already on for a different criterion. A community runs it on at most one criterion, because enrolment, the drip and the challenge are served from a single configuration. Withdraw it from the other criterion first.
    ///
    /// Declared `retryable: false`.
    pub const OTHER_CRITERION: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/vetting/hidden/publish:otherCriterion",
        retryable: false,
    };
}
